//! Full-bag request1..28 caps and per-step fractional XP after mixed breaks.
use gielinor_world::{grinding,tool_crafting::{Recipe,Failure},held_use::{Handler,Scope,Type,Request},inventory::Item,simulation::{World,PlayerData,WorldEvent},stats::Stats,npc::RandomSource,CoordGrid};use std::sync::Arc;
struct Draw{calls:usize,limit:usize}impl RandomSource for Draw{fn below(&mut self,n:u32)->u32{assert_eq!(n,256);assert!(self.calls<self.limit);let v=if self.calls%2==0{0}else{255};self.calls+=1;v}}
#[test]fn one_hundred_twelve_full_bag_counts_cap_selected_order_and_round_each_success(){let mut cases=0;for(raw,out,broken)in[(7538,7539,7541),(7536,7537,7540)]{for reverse in[false,true]{for count in 1..=28{let r=Recipe{exchange:grinding::Recipe{tool:1755,input:raw,output:out,members:true,animation:Some(1280)},level:15,xp_tenths:325,ticks:3,name:"Crab material",action:"carve",failure:Some(Failure{output:broken,xp_tenths:0,low:40,high:240,message:"You accidentally break the crab material."})};let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(12,99);stats.set_current(12,99);stats.set_fine_xp(12,130344311).unwrap();let mut w=World::default();w.collision.allocate(3200,3200,0);let mut d=PlayerData::new(1,"Independent crab quantity caps".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);d.xp_rate_hundreds=125;for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:if s<2{1755}else if s==27{995}else{raw},count:if s==27{1000}else{1},vars:0})).unwrap();}w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,true).unwrap();for id in[1755,raw]{w.held_use_types.insert(id,Type{id,content:-1});}w.held_use_handlers.register(Scope::Types,1755,raw,Handler::ToolCraftingChoices{recipes:Arc::new(vec![r]),cycle_ticks:3}).unwrap();let h=if reverse{Request{selected_slot:17,selected_id:raw,target_slot:0,target_id:1755}}else{Request{selected_slot:0,selected_id:1755,target_slot:17,target_id:raw}};w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();let q=w.take_tool_crafting_request(a).unwrap().unwrap();let before=w.data(a).unwrap().clone();let mut inv=before.inventory.clone();let mut xp=before.stats.clone();w.drain_events();w.start_tool_crafting_choice(a,q,0,count).unwrap();assert_eq!(w.data(a).unwrap().inventory,inv);let limit=count.min(25) as usize;let mut rng=Draw{calls:0,limit};let order=std::iter::once(17).chain((2..27).filter(|s|*s!=17)).collect::<Vec<_>>();let start=w.clock.0;let mut seen=0;for _ in 0..(4+3*limit+8){w.tick_with_random(&mut rng).unwrap();if rng.calls!=seen{assert_eq!(rng.calls,seen+1);assert_eq!(w.clock.0-start,4+3*seen as i32);let good=seen%2==0;inv.restore_slot(order[seen],Some(Item{id:if good{out}else{broken},count:1,vars:0})).unwrap();if good{xp.set_fine_xp(12,xp.fine_xp(12)+406).unwrap();}seen+=1;}assert_eq!(w.data(a).unwrap().inventory,inv,"count{count}");assert_eq!(w.data(a).unwrap().stats,xp,"count{count}");}assert_eq!(rng.calls,limit);assert_eq!(inv.free_space(),0);assert_eq!(inv.get(0).unwrap().id,1755);assert_eq!(inv.get(1).unwrap().id,1755);assert_eq!(inv.get(27).unwrap().count,1000);assert_eq!(w.drain_events().iter().filter(|e|matches!(e,WorldEvent::SkillAdvanced{..})).count(),(limit+1)/2);cases+=1;}}}assert_eq!(cases,112);}
